 3→/// Broadcasts channel events over the gateway WebSocket.
 4→///
 5→/// Uses a deferred `OnceCell` reference so the sink can be created before
 6→/// `GatewayState` exists (same pattern as cron callbacks).
 7→pub struct GatewayChannelEventSink {
 8→    pub(super) state: Arc<tokio::sync::OnceCell<Arc<GatewayState>>>,
 9→}
10→
