17→pub(super) async fn emit(
18→    state: &Arc<tokio::sync::OnceCell<Arc<GatewayState>>>,
19→    event: ChannelEvent,
20→) {
21→    if let Some(state) = state.get() {
22→        let payload = match serde_json::to_value(&event) {
23→            Ok(v) => v,
24→            Err(e) => {
25→                warn!("failed to serialize channel event: {e}");
26→                return;
27→            },
28→        };
29→
30→        // Render QR data as an SVG so the frontend can display it directly.
31→        #[cfg(feature = "whatsapp")]
32→        let payload = {
33→            let mut payload = payload;
34→            if let ChannelEvent::PairingQrCode { ref qr_data, .. } = event
35→                && let Ok(code) = qrcode::QrCode::new(qr_data)
36→            {
37→                let svg = code
38→                    .render::<qrcode::render::svg::Color>()
39→                    .min_dimensions(200, 200)
40→                    .quiet_zone(true)
41→                    .build();
42→                if let serde_json::Value::Object(ref mut map) = payload {
43→                    map.insert("qr_svg".into(), serde_json::Value::String(svg));
44→                }
45→            }
46→            payload
47→        };
48→
49→        broadcast(state, "channel", payload, BroadcastOpts {
50→            drop_if_slow: true,
51→            ..Default::default()
52→        })
53→        .await;
54→    }
55→}
