 16→/// Start a WhatsApp connection for the given account.
 17→///
 18→/// Builds the `Bot` with a persistent sled store, registers the event handler,
 19→/// and spawns the event loop as a background tokio task. Session state persists
 20→/// across restarts so the user does not need to re-scan the QR code.
 21→pub async fn start_connection(
 22→    account_id: String,
 23→    config: WhatsAppAccountConfig,
 24→    accounts: AccountStateMap,
 25→    data_dir: std::path::PathBuf,
 26→    message_log: Option<Arc<dyn MessageLog>>,
 27→    event_sink: Option<Arc<dyn ChannelEventSink>>,
 28→) -> crate::Result<()> {
 29→    // Use persistent sled store at <data_dir>/whatsapp/<account_id>/.
 30→    let store_path = config
 31→        .store_path
 32→        .clone()
 33→        .unwrap_or_else(|| data_dir.join("whatsapp").join(&account_id));
 34→
 35→    info!(account_id = %account_id, path = %store_path.display(), "opening sled WhatsApp store");
 36→
 37→    let backend = Arc::new(
 38→        crate::sled_store::SledStore::open(&store_path).map_err(|e| crate::Error::Store {
 39→            message: format!("failed to open sled store at {}: {e}", store_path.display()),
 40→        })?,
 41→    );
 42→
 43→    let cancel = CancellationToken::new();
 44→    let cancel_clone = cancel.clone();
 45→    let shutdown = Arc::new(ShutdownState::new());
 46→    let shutdown_clone = Arc::clone(&shutdown);
 47→
 48→    // Build the bot.
 49→    let account_id_clone = account_id.clone();
 50→    let event_sink_clone = event_sink.clone();
 51→    let message_log_clone = message_log.clone();
 52→
 53→    // We need to create a temporary accounts ref for the state that will be
 54→    // populated after bot.build().
 55→    let state_ref: Arc<tokio::sync::OnceCell<Arc<AccountState>>> =
 56→        Arc::new(tokio::sync::OnceCell::new());
 57→    let state_ref_handler = Arc::clone(&state_ref);
 58→    let accounts_handler = Arc::clone(&accounts);
 59→
 60→    let mut bot = whatsapp_rust::bot::Bot::builder()
 61→        .with_backend(backend)
 62→        .with_transport_factory(
 63→            whatsapp_rust_tokio_transport::TokioWebSocketTransportFactory::new(),
 64→        )
 65→        .with_http_client(whatsapp_rust_ureq_http_client::UreqHttpClient::new())
 66→        .with_runtime(whatsapp_rust::TokioRuntime)
 67→        .on_event(move |event, client| {
 68→            let state_ref = Arc::clone(&state_ref_handler);
 69→            let accounts = Arc::clone(&accounts_handler);
 70→            async move {
 71→                if let Some(state) = state_ref.get() {
 72→                    handlers::handle_event(event, client, Arc::clone(state), accounts).await;
 73→                }
 74→            }
 75→        })
 76→        .build()
 77→        .await
 78→        .map_err(|e| crate::Error::Whatsapp {
 79→            message: e.to_string(),
 80→        })?;
 81→
 82→    let client = bot.client();
 83→
 84→    // Create account state.
 85→    let otp_cooldown = config.otp_cooldown_secs;
 86→    let account_state = Arc::new(AccountState {
 87→        client: Arc::clone(&client),
 88→        account_id: account_id_clone.clone(),
 89→        config,
 90→        cancel: cancel_clone,
 91→        shutdown: Arc::clone(&shutdown),
 92→        message_log: message_log_clone,
 93→        event_sink: event_sink_clone,
 94→        latest_qr: std::sync::RwLock::new(None),
 95→        connected: std::sync::atomic::AtomicBool::new(false),
 96→        otp: std::sync::Mutex::new(crate::otp::OtpState::new(otp_cooldown)),
 97→        recent_sent_ids: std::sync::Mutex::new(std::collections::VecDeque::new()),
 98→    });
 99→
100→    // Populate the OnceCell so the event handler can access state.
101→    let _ = state_ref.set(Arc::clone(&account_state));
102→
103→    // Insert into the shared map.
104→    {
105→        let mut map = accounts.write().unwrap_or_else(|e| e.into_inner());
106→        map.insert(account_id.clone(), AccountState {
107→            client: Arc::clone(&client),
108→            account_id: account_id.clone(),
109→            config: account_state.config.clone(),
110→            cancel: cancel.clone(),
111→            shutdown: Arc::clone(&shutdown),
112→            message_log: account_state.message_log.clone(),
113→            event_sink: account_state.event_sink.clone(),
114→            latest_qr: std::sync::RwLock::new(None),
115→            connected: std::sync::atomic::AtomicBool::new(false),
116→            otp: std::sync::Mutex::new(crate::otp::OtpState::new(otp_cooldown)),
117→            recent_sent_ids: std::sync::Mutex::new(std::collections::VecDeque::new()),
118→        });
119→    }
120→
121→    // Spawn the event loop.
122→    let account_id_task = account_id.clone();
123→    tokio::spawn(async move {
124→        tokio::select! {
125→            result = bot.run() => {
126→                match result {
127→                    Ok(handle) => {
128→                        tokio::pin!(handle);
129→                        tokio::select! {
130→                            _ = &mut handle => {
131→                                info!(account_id = %account_id_task, "WhatsApp bot task completed");
132→                            },
133→                            _ = cancel.cancelled() => {
134→                                info!(account_id = %account_id_task, "WhatsApp account cancelled, aborting bot task");
135→                                handle.abort();
136→                                // Wait for the task to finish after abort so the
137→                                // sled store is fully released before we signal done.
138→                                let _ = handle.await;
139→                            },
140→                        }
141→                    },
142→                    Err(e) => {
143→                        warn!(account_id = %account_id_task, error = %e, "WhatsApp bot failed to start");
144→                    },
145→                }
146→            },
147→            _ = cancel.cancelled() => {
148→                info!(account_id = %account_id_task, "WhatsApp account cancelled before start");
149→            },
150→        }
151→        shutdown_clone.mark_done();
152→    });
153→
154→    Ok(())
155→}
