113→/// Check whether `sender_id` is on the channel account's DM allowlist.
114→///
115→/// The DM allowlist is the source of truth for privileged command access:
116→/// anyone allowed to DM the bot is trusted to run commands like `/approve`
117→/// and `/deny` from any context (DM or group). Users not on the allowlist
118→/// can still chat (if group policy permits) but cannot run privileged
119→/// commands.
120→///
121→/// Returns `false` when the allowlist is empty (open DM policy) because an
122→/// open policy means no one has been explicitly authorized.
123→async fn is_sender_on_allowlist(
124→    state: &Arc<GatewayState>,
125→    account_id: &str,
126→    sender_id: &str,
127→) -> bool {
128→    let Some(ref registry) = state.services.channel_registry else {
129→        return false;
130→    };
131→    let Some(config) = registry.account_config(account_id).await else {
132→        return false;
133→    };
134→    let allowlist = config.allowlist();
135→    // Empty allowlist = open policy → no explicit authorization.
136→    if allowlist.is_empty() {
137→        return false;
138→    }
139→    // Check the full sender_id first, then try the user part before '@'
140→    // (WhatsApp JIDs are e.g. "15551234567@s.whatsapp.net" but allowlists
141→    // use plain phone numbers like "15551234567").
142→    moltis_channels::gating::is_allowed(sender_id, allowlist)
143→        || sender_id
144→            .split_once('@')
145→            .is_some_and(|(user, _)| moltis_channels::gating::is_allowed(user, allowlist))
146→}
