193→				window.location.assign("/onboarding");
194→			} else if (auth && !auth.authenticated) {
195→				window.location.assign("/login");
196→			} else {
197→				scheduleReconnect(() => connectWs(opts), backoff);
198→			}
199→		})
200→		.catch(() => {
201→			// Auth check itself failed — fall back to normal reconnect.
202→			scheduleReconnect(() => connectWs(opts), backoff);
203→		});
204→}
