206→function scheduleReconnect(reconnect, backoff) {
207→	if (reconnectTimer) return;
208→	reconnectTimer = setTimeout(() => {
209→		reconnectTimer = null;
210→		S.setReconnectDelay(Math.min(S.reconnectDelay * backoff.factor, backoff.max));
