167→fn truncate_preview(text: &str, max_chars: usize) -> String {
168→    let mut chars = text.chars();
169→    let mut out = String::new();
170→    for _ in 0..max_chars {
171→        if let Some(ch) = chars.next() {
172→            out.push(ch);
173→        } else {
174→            return out;
175→        }
176→    }
177→    if chars.next().is_some() {
178→        out.push('…');
179→    }
180→    out
181→}
