196→async fn build_recent_sessions_snapshot(gw: &GatewayState, limit: usize) -> Vec<serde_json::Value> {
197→    let Some(ref metadata) = gw.services.session_metadata else {
198→        return Vec::new();
199→    };
200→
201→    let mut recent = Vec::new();
202→    for entry in metadata.list().await.into_iter().take(limit) {
203→        let active_channel = if let Some(ref binding_json) = entry.channel_binding {
204→            if let Ok(target) =
205→                serde_json::from_str::<moltis_channels::ChannelReplyTarget>(binding_json)
206→            {
207→                metadata
208→                    .get_active_session(
209→                        target.channel_type.as_str(),
210→                        &target.account_id,
211→                        &target.chat_id,
212→                        target.thread_id.as_deref(),
213→                    )
214→                    .await
215→                    .unwrap_or_else(|| default_channel_session_key(&target))
216→                    == entry.key
217→            } else {
218→                false
219→            }
220→        } else {
221→            false
222→        };
223→        let preview = entry
224→            .preview
225→            .as_deref()
226→            .map(|text| truncate_preview(text, SESSION_PREVIEW_MAX_CHARS));
227→        let agent_id = entry.agent_id.clone().unwrap_or_else(|| "main".to_owned());
228→        let agent_id_camel = agent_id.clone();
229→
230→        recent.push(serde_json::json!({
231→            "id": entry.id,
232→            "key": entry.key,
233→            "label": entry.label,
234→            "model": entry.model,
235→            "createdAt": entry.created_at,
236→            "updatedAt": entry.updated_at,
237→            "messageCount": entry.message_count,
238→            "lastSeenMessageCount": entry.last_seen_message_count,
239→            "projectId": entry.project_id,
240→            "sandbox_enabled": entry.sandbox_enabled,
241→            "sandbox_image": entry.sandbox_image,
242→            "worktree_branch": entry.worktree_branch,
243→            "channelBinding": entry.channel_binding,
244→            "activeChannel": active_channel,
245→            "parentSessionKey": entry.parent_session_key,
246→            "forkPoint": entry.fork_point,
247→            "mcpDisabled": entry.mcp_disabled,
248→            "preview": preview,
249→            "archived": entry.archived,
250→            "agent_id": agent_id,
251→            "agentId": agent_id_camel,
252→            "node_id": entry.node_id,
