	saveProviderKey,
	testModel,
	validateProviderKey,
} from "./provider-validation.js";
import * as S from "./state.js";
import { fetchPhrase } from "./tts-phrases.js";
import {
	decodeBase64Safe,
	fetchVoiceProviders,
	saveVoiceKey,
	saveVoiceSettings,
	testTts,
	toggleVoiceProvider,
	transcribeAudio,
	VOICE_COUNTERPART_IDS,
} from "./voice-utils.js";
import { connectWs } from "./ws-connect.js";

var wsStarted = false;
function ensureWsConnected() {
	if (wsStarted) return;
	wsStarted = true;
	connectWs({
		backoff: { factor: 2, max: 10000 },
		onFrame: (frame) => {
			if (frame.type !== "event") return;
			var listeners = eventListeners[frame.event] || [];
			listeners.forEach((h) => {
				h(frame.payload || {});
			});
		},
	});
}

var WS_RETRY_LIMIT = 75;
var WS_RETRY_DELAY_MS = 200;

// ── Step indicator ──────────────────────────────────────────

function preferredChatPath() {
	var key = localStorage.getItem("moltis-session") || "main";
	return `/chats/${key.replace(/:/g, "/")}`;
}

function detectBrowserTimezone() {
	try {
		var timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
		return typeof timezone === "string" ? timezone.trim() : "";
	} catch {
		return "";
	}
}

function ErrorPanel({ message }) {
