				placeholder="e.g. my_assistant_bot"
				autocomplete="off"
				autocapitalize="none"
				autocorrect="off"
				spellcheck="false"
				name="telegram_bot_username"
				autofocus />
		</div>
		<div>
			<label class="text-xs text-[var(--muted)] mb-1 block">Bot token (from @BotFather)</label>
			<input type="password" class="provider-key-input w-full"
