		</div>
		<div>
			<label class="text-xs text-[var(--muted)] mb-1 block">Your Telegram username(s)</label>
			<textarea class="provider-key-input w-full" rows="2"
				value=${allowlist} onInput=${(e) => setAllowlist(e.target.value)}
