// ── Add Matrix modal ─────────────────────────────────────────
function AddMatrixModal() {
	var error = useSignal("");
	var saving = useSignal(false);
	var addModel = useSignal("");
	var userAllowlistItems = useSignal([]);
	var roomAllowlistItems = useSignal([]);
	var homeserverDraft = useSignal(MATRIX_DEFAULT_HOMESERVER);
