      </select>
      ${
				!isWhatsApp &&
				html`
        <label class="text-xs text-[var(--muted)]">Group Mention Mode</label>
        <select data-field="mentionMode" class="channel-select" value=${cfg.mention_mode || "mention"}>
          <option value="mention">Must @mention bot</option>
