	var [roomAllowlist, setRoomAllowlist] = useState("");
	var [advancedConfig, setAdvancedConfig] = useState("");
	var [saving, setSaving] = useState(false);

	function splitLines(value) {
		return value
			.trim()
			.split(/\n/)
			.map((s) => s.trim())
			.filter(Boolean);
	}

	function onSubmit(e) {
		e.preventDefault();
