		modelsSig.value.length > 0
			? `(default: ${modelsSig.value[0].displayName || modelsSig.value[0].id})`
			: "(server default)";

	return html`<${Modal} show=${showAddMatrix.value} onClose=${() => {
		showAddMatrix.value = false;
	}}
