// ── Add Telegram modal ───────────────────────────────────────
function AddTelegramModal() {
	var error = useSignal("");
	var saving = useSignal(false);
	var addModel = useSignal("");
	var allowlistItems = useSignal([]);
	var accountDraft = useSignal("");
	var advancedConfigPatch = useSignal("");

	function onSubmit(e) {
		e.preventDefault();
