			{ providerName: "Venice", linkName: "Venice Settings" },
			{ providerName: "OpenRouter", linkName: "OpenRouter Settings" },
			{ providerName: "Moonshot", linkName: "Moonshot Platform" },
			{ providerName: "MiniMax", linkName: "MiniMax Platform" },
