			state.setWs({
				readyState: wsOpen,
				send(raw) {
					const req = JSON.parse(raw || "{}");
					const resolver = state.pending[req.id];
					if (!resolver) return;
					if (req.method === "voice.config.save_settings") {
						window.__voiceOnboardingSaveSettingsRequest = req.params || null;
