		const sentRequest = await page.evaluate(() => window.__voiceOnboardingSaveSettingsRequest);
		expect(sentRequest).toMatchObject({
			provider: "whisper",
			baseUrl: "http://127.0.0.1:8001/v1",
		});
		expect(pageErrors).toEqual([]);
	});
});

