245→export function highlightAndScroll(msgEls, messageIndex, query) {
246→	var target = null;
247→	if (messageIndex >= 0 && messageIndex < msgEls.length && msgEls[messageIndex]) {
248→		target = msgEls[messageIndex];
249→	}
250→	var lowerQ = query.toLowerCase();
251→	if (!target || (target.textContent || "").toLowerCase().indexOf(lowerQ) === -1) {
252→		for (var candidate of msgEls) {
253→			if (candidate && (candidate.textContent || "").toLowerCase().indexOf(lowerQ) !== -1) {
254→				target = candidate;
255→				break;
256→			}
257→		}
258→	}
259→	if (!target) return;
260→	msgEls.forEach((el) => {
261→		if (el) highlightTermInElement(el, query);
262→	});
263→	target.scrollIntoView({ behavior: "smooth", block: "center" });
264→	target.classList.add("search-highlight-msg");
265→	setTimeout(() => {
266→		if (!S.chatMsgBox) return;
267→		S.chatMsgBox.querySelectorAll("mark.search-term-highlight").forEach((m) => {
268→			var parent = m.parentNode;
269→			parent.replaceChild(document.createTextNode(m.textContent), m);
270→			parent.normalize();
271→		});
272→		S.chatMsgBox.querySelectorAll(".search-highlight-msg").forEach((el) => {
273→			el.classList.remove("search-highlight-msg");
274→		});
275→	}, 5000);
276→}
277→
278→export function highlightTermInElement(el, query) {
279→	var walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, null, false);
280→	var nodes = [];
281→	while (walker.nextNode()) nodes.push(walker.currentNode);
282→	var lowerQ = query.toLowerCase();
283→	nodes.forEach((textNode) => {
284→		var text = textNode.nodeValue;
285→		var lowerText = text.toLowerCase();
286→		var idx = lowerText.indexOf(lowerQ);
287→		if (idx === -1) return;
288→		var frag = document.createDocumentFragment();
289→		var pos = 0;
290→		while (idx !== -1) {
291→			if (idx > pos) frag.appendChild(document.createTextNode(text.substring(pos, idx)));
292→			var mark = document.createElement("mark");
293→			mark.className = "search-term-highlight";
294→			mark.textContent = text.substring(idx, idx + query.length);
295→			frag.appendChild(mark);
296→			pos = idx + query.length;
297→			idx = lowerText.indexOf(lowerQ, pos);
298→		}
299→		if (pos < text.length) frag.appendChild(document.createTextNode(text.substring(pos)));
300→		textNode.parentNode.replaceChild(frag, textNode);
301→	});
302→}
