301→export function markSessionLocallyCleared(key) {
302→	if (!key) return;
303→	var now = Date.now();
304→
305→	var session = sessionStore.getByKey(key);
306→	if (session) {
307→		session.syncCounts(0, 0);
308→		session.preview = "";
309→		session.updatedAt = now;
310→		session.replying.value = false;
311→		session.activeRunId.value = null;
312→		session.lastHistoryIndex.value = -1;
