319→	if (legacy) {
320→		legacy.messageCount = 0;
321→		legacy.lastSeenMessageCount = 0;
322→		legacy.preview = "";
323→		legacy.updatedAt = now;
324→		legacy._localUnread = false;
325→		legacy._replying = false;
326→		legacy._activeRunId = null;
327→		var legacyVersion = Number.isInteger(legacy.version) ? legacy.version : 0;
