446→function setHistoryPaginationState(key, payload) {
447→	if (!key) return;
448→	var hasMore = payload?.hasMore === true;
449→	var nextCursor = toValidHistoryIndex(payload?.nextCursor);
450→	var totalMessages = Number(payload?.totalMessages);
451→	sessionHistoryPaging.set(key, {
452→		hasMore: hasMore && nextCursor !== null,
453→		nextCursor: hasMore ? nextCursor : null,
454→		totalMessages: Number.isInteger(totalMessages) && totalMessages >= 0 ? totalMessages : null,
455→		loadingOlder: false,
456→	});
457→}
