468→function historyIndexFromMessage(message) {
469→	if (!(message && typeof message === "object")) return null;
470→	var idx = toValidHistoryIndex(message.historyIndex);
471→	if (idx !== null) return idx;
472→	return toValidHistoryIndex(message.messageIndex);
473→}
