475→function computeHistoryTailIndex(history) {
476→	var max = -1;
477→	if (!Array.isArray(history)) return max;
478→	for (var i = 0; i < history.length; i += 1) {
479→		var indexed = historyIndexFromMessage(history[i]);
480→		if (indexed !== null) {
481→			if (indexed > max) max = indexed;
482→			continue;
483→		}
484→		if (i > max) max = i;
485→	}
486→	return max;
487→}
