925→function mergeHistoryPages(existingHistory, olderHistory) {
926→	var older = Array.isArray(olderHistory) ? olderHistory : [];
927→	var current = Array.isArray(existingHistory) ? existingHistory : [];
928→	if (older.length === 0) return current;
929→	if (current.length === 0) return older;
930→
931→	var byIndex = new Map();
932→	var ordered = [];
933→	var pushMessage = (msg) => {
934→		var idx = historyIndexFromMessage(msg);
935→		if (idx === null) {
936→			ordered.push(msg);
937→			return;
938→		}
939→		if (!byIndex.has(idx)) {
940→			ordered.push(msg);
941→		}
942→		byIndex.set(idx, msg);
943→	};
944→
945→	for (var olderMsg of older) pushMessage(olderMsg);
946→	for (var currentMsg of current) pushMessage(currentMsg);
947→
948→	return ordered.map((msg) => {
949→		var idx = historyIndexFromMessage(msg);
950→		if (idx === null) return msg;
951→		return byIndex.get(idx) || msg;
952→	});
953→}
