  1→//! Typed parameter structs for complex session RPC methods.
  2→//!
  3→//! Only methods with non-trivial parameter shapes (multi-field with defaults,
  4→//! null-vs-absent semantics, precedence logic) get dedicated structs here.
  5→//! Simple key-only handlers use inline `.get(...)` directly.
  6→
  7→use serde::Deserialize;
  8→
  9→use crate::services::ServiceError;
 10→
 11→/// Params for `session.patch`.
 12→///
 13→/// All fields except `key` are optional — only provided fields are updated.
 14→///
 15→/// Fields that can be cleared (set to null) use `Option<Option<String>>`:
 16→/// - outer `None` → field was absent from the request (no-op)
 17→/// - `Some(None)` → field was explicitly `null` (clear it)
 18→/// - `Some(Some(v))` → field was set to value `v`
 19→#[derive(Debug, Deserialize)]
 20→#[serde(rename_all = "camelCase")]
 21→pub struct PatchParams {
 22→    pub key: String,
 23→    #[serde(default)]
 24→    pub label: Option<String>,
 25→    #[serde(default)]
 26→    pub model: Option<String>,
 27→    #[serde(default)]
 28→    pub archived: Option<bool>,
 29→    #[serde(default, deserialize_with = "double_option", alias = "project_id")]
 30→    pub project_id: Option<Option<String>>,
 31→    #[serde(default, deserialize_with = "double_option", alias = "worktree_branch")]
 32→    pub worktree_branch: Option<Option<String>>,
 33→    #[serde(default, deserialize_with = "double_option", alias = "sandbox_image")]
 34→    pub sandbox_image: Option<Option<String>>,
 35→    #[serde(default, deserialize_with = "double_option", alias = "mcp_disabled")]
 36→    pub mcp_disabled: Option<Option<bool>>,
 37→    #[serde(default, deserialize_with = "double_option", alias = "sandbox_enabled")]
 38→    pub sandbox_enabled: Option<Option<bool>>,
 39→}
 40→
 41→/// Deserialize a field as `Some(inner)` when present (even if null),
 42→/// vs `None` when absent (via `#[serde(default)]`).
 43→fn double_option<'de, T, D>(deserializer: D) -> Result<Option<Option<T>>, D::Error>
 44→where
 45→    T: Deserialize<'de>,
 46→    D: serde::Deserializer<'de>,
 47→{
 48→    Ok(Some(Option::<T>::deserialize(deserializer)?))
 49→}
