 51→/// Params for `session.voice_generate`.
 52→#[derive(Debug, Deserialize)]
 53→#[serde(rename_all = "camelCase")]
 54→pub struct VoiceGenerateParams {
 55→    pub key: String,
 56→    #[serde(default)]
 57→    pub run_id: Option<String>,
 58→    #[serde(default)]
 59→    pub message_index: Option<usize>,
 60→    #[serde(default)]
 61→    pub history_index: Option<usize>,
 62→}
 63→
 64→impl VoiceGenerateParams {
 65→    /// Resolve the target specification. `run_id` takes precedence.
 66→    pub fn target(&self) -> Result<VoiceTarget, &'static str> {
 67→        if let Some(ref id) = self.run_id {
 68→            let trimmed = id.trim();
 69→            if !trimmed.is_empty() {
 70→                return Ok(VoiceTarget::ByRunId(trimmed.to_string()));
 71→            }
 72→        }
 73→        if let Some(idx) = self.message_index.or(self.history_index) {
 74→            return Ok(VoiceTarget::ByMessageIndex(idx));
 75→        }
 76→        Err("missing 'messageIndex' or 'runId' parameter")
 77→    }
 78→}
