 80→/// How to locate the target assistant message for voice generation.
 81→#[derive(Debug, Clone, PartialEq, Eq)]
 82→pub enum VoiceTarget {
 83→    /// Locate by agent run ID (stable across inserted tool_result messages).
 84→    ByRunId(String),
 85→    /// Locate by raw message index in the history array.
 86→    ByMessageIndex(usize),
 87→}
