 89→/// Parse a `serde_json::Value` into a typed param struct, mapping
 90→/// deserialization errors to the service error format.
 91→pub fn parse_params<T: serde::de::DeserializeOwned>(
 92→    params: serde_json::Value,
 93→) -> Result<T, ServiceError> {
 94→    serde_json::from_value(params).map_err(ServiceError::message)
 95→}
