 10→// ── Broadcaster ──────────────────────────────────────────────────────────────
 11→
 12→/// Lock-free broadcast state: sequence counter and GraphQL subscription channel.
 13→///
 14→/// Phase 1 of broadcaster decoupling — owns only fields that never participate
 15→/// in the `GatewayInner` RwLock. Client registry remains in `GatewayInner`
 16→/// to preserve atomic compound operations.
 17→pub struct Broadcaster {
 18→    /// Monotonically increasing sequence counter for broadcast events.
 19→    seq: std::sync::atomic::AtomicU64,
 20→    /// Broadcast channel for GraphQL subscriptions. Events are `(event_name, payload)`.
 21→    #[cfg(feature = "graphql")]
 22→    pub graphql_broadcast: tokio::sync::broadcast::Sender<(String, serde_json::Value)>,
 23→}
 24→
 25→impl Default for Broadcaster {
 26→    fn default() -> Self {
 27→        Self::new()
 28→    }
 29→}
 30→
 31→impl Broadcaster {
 32→    /// Create a new Broadcaster with sequence starting at 0.
 33→    pub fn new() -> Self {
 34→        Self {
 35→            seq: std::sync::atomic::AtomicU64::new(0),
 36→            #[cfg(feature = "graphql")]
 37→            graphql_broadcast: {
 38→                let (tx, _) = tokio::sync::broadcast::channel(256);
 39→                tx
 40→            },
 41→        }
 42→    }
 43→
 44→    /// Return the next sequence number.
 45→    #[must_use]
 46→    pub fn next_seq(&self) -> u64 {
 47→        self.seq.fetch_add(1, std::sync::atomic::Ordering::Relaxed) + 1
 48→    }
 49→}
