 51→// ── Scope guards ─────────────────────────────────────────────────────────────
 52→
 53→/// Events that require specific scopes to receive.
 54→fn event_scope_guards() -> HashMap<&'static str, &'static [&'static str]> {
 55→    let mut m = HashMap::new();
 56→    m.insert("exec.approval.requested", [scopes::APPROVALS].as_slice());
 57→    m.insert("exec.approval.resolved", [scopes::APPROVALS].as_slice());
 58→    m.insert("device.pair.requested", [scopes::PAIRING].as_slice());
 59→    m.insert("device.pair.resolved", [scopes::PAIRING].as_slice());
 60→    m.insert("node.pair.requested", [scopes::PAIRING].as_slice());
 61→    m.insert("node.pair.resolved", [scopes::PAIRING].as_slice());
 62→    m
 63→}
