 65→// ── Broadcast options ────────────────────────────────────────────────────────
 66→
 67→#[derive(Default)]
 68→pub struct BroadcastOpts {
 69→    pub drop_if_slow: bool,
 70→    pub state_version: Option<StateVersion>,
 71→    /// Stream group ID for chunked delivery (v4).
 72→    pub stream: Option<String>,
 73→    /// End-of-stream marker (v4).
 74→    pub done: bool,
 75→    /// Logical channel for multiplexing (v4).
 76→    pub channel: Option<String>,
 77→}
 78→
 79→// ── Broadcast ───────────────────────────────────────────────────────────────
 80→
 81→/// Broadcast events to all connected WebSocket clients, respecting scope
 82→/// guards and dropping/closing slow consumers.
 83→pub async fn broadcast(
 84→    state: &Arc<GatewayState>,
 85→    event: &str,
 86→    payload: serde_json::Value,
 87→    opts: BroadcastOpts,
 88→) {
 89→    let seq = state.broadcaster.next_seq();
 90→    let stream = opts.stream.clone();
 91→    let done = opts.done.then_some(true);
 92→    let channel = opts.channel.clone();
 93→    let frame = EventFrame {
 94→        r#type: "event".into(),
 95→        event: event.into(),
 96→        payload: Some(payload),
 97→        seq: Some(seq),
 98→        state_version: opts.state_version,
 99→        stream,
100→        done,
101→        channel,
102→    };
103→    let json = match serde_json::to_string(&frame) {
104→        Ok(j) => j,
105→        Err(e) => {
106→            warn!("failed to serialize broadcast event: {e}");
107→            return;
108→        },
109→    };
110→
111→    // Forward to GraphQL subscription broadcast channel.
112→    #[cfg(feature = "graphql")]
113→    if let Some(ref payload) = frame.payload {
114→        let _ = state
115→            .broadcaster
116→            .graphql_broadcast
117→            .send((event.to_string(), payload.clone()));
118→    }
119→
120→    let guards = event_scope_guards();
121→    let required_scopes = guards.get(event);
122→
123→    let inner = state.inner.read().await;
124→    debug!(
125→        event,
126→        seq,
127→        clients = inner.clients.len(),
128→        "broadcasting event"
129→    );
130→    for client in inner.clients.values() {
131→        // Check scope guard: if the event requires a scope, verify the client has it.
132→        if let Some(required) = required_scopes {
133→            let client_scopes = client.scopes();
134→            let has = client_scopes.contains(&scopes::ADMIN)
135→                || required.iter().any(|s| client_scopes.contains(s));
136→            if !has {
137→                continue;
138→            }
139→        }
140→
141→        // Subscription filter (v4): skip clients not subscribed to this event.
142→        if !client.is_subscribed_to(event) {
143→            continue;
144→        }
145→
146→        // Channel filter (v4): if event is scoped to a channel, skip clients
147→        // that haven't joined it.
148→        if let Some(ref ch) = opts.channel
149→            && !client.is_in_channel(ch)
150→        {
151→            continue;
152→        }
153→
154→        if !client.send(&json) && opts.drop_if_slow {
155→            // Channel full or closed — skip silently when drop_if_slow.
156→            continue;
157→        }
158→    }
159→}
