 20→/// Convert session-crate `MessageContent` to agents-crate `UserContent`.
 21→///
 22→/// The two types have different image representations:
 23→/// - `ContentBlock::ImageUrl` stores a data URI string
 24→/// - `ContentPart::Image` stores separated `media_type` + `data` fields
 25→pub(crate) fn format_user_documents_context(documents: &[UserDocument]) -> Option<String> {
 26→    if documents.is_empty() {
 27→        return None;
 28→    }
 29→
 30→    let mut sections = Vec::with_capacity(documents.len() + 1);
 31→    sections.push("[Inbound documents available]".to_string());
 32→    for document in documents {
 33→        sections.push(format!(
 34→            "filename: {}\nmime_type: {}\nlocal_path: {}\nmedia_ref: {}",
 35→            document.display_name,
 36→            document.mime_type,
 37→            document
 38→                .absolute_path
 39→                .as_deref()
 40→                .unwrap_or(&document.media_ref),
 41→            document.media_ref
 42→        ));
 43→    }
 44→
 45→    Some(sections.join("\n\n"))
 46→}
 47→
 48→pub(crate) fn append_user_documents_to_text(text: &str, documents: &[UserDocument]) -> String {
 49→    if let Some(context) = format_user_documents_context(documents) {
 50→        if text.trim().is_empty() {
 51→            context
 52→        } else {
 53→            format!("{text}\n\n{context}")
 54→        }
 55→    } else {
 56→        text.to_string()
 57→    }
 58→}
 59→
 60→pub(crate) fn to_user_content(mc: &MessageContent, documents: &[UserDocument]) -> UserContent {
 61→    match mc {
 62→        MessageContent::Text(text) => {
 63→            UserContent::Text(append_user_documents_to_text(text, documents))
 64→        },
 65→        MessageContent::Multimodal(blocks) => {
 66→            let mut parts: Vec<ContentPart> = blocks
 67→                .iter()
 68→                .filter_map(|block| match block {
 69→                    ContentBlock::Text { text } => Some(ContentPart::Text(text.clone())),
 70→                    ContentBlock::ImageUrl { image_url } => match parse_data_uri(&image_url.url) {
 71→                        Some((media_type, data)) => {
 72→                            debug!(
 73→                                media_type,
 74→                                data_len = data.len(),
 75→                                "to_user_content: parsed image from data URI"
 76→                            );
 77→                            Some(ContentPart::Image {
 78→                                media_type: media_type.to_string(),
 79→                                data: data.to_string(),
 80→                            })
 81→                        },
 82→                        None => {
 83→                            warn!(
 84→                                url_prefix = truncate_at_char_boundary(&image_url.url, 80),
 85→                                "to_user_content: failed to parse data URI, dropping image"
 86→                            );
 87→                            None
 88→                        },
 89→                    },
 90→                })
 91→                .collect();
 92→            if let Some(context) = format_user_documents_context(documents) {
 93→                if let Some(ContentPart::Text(text)) = parts
 94→                    .iter_mut()
 95→                    .find(|part| matches!(part, ContentPart::Text(_)))
 96→                {
 97→                    if !text.trim().is_empty() {
 98→                        text.push_str("\n\n");
 99→                    }
100→                    text.push_str(&context);
101→                } else {
102→                    parts.insert(0, ContentPart::Text(context));
103→                }
104→            }
105→            let text_count = parts
106→                .iter()
107→                .filter(|p| matches!(p, ContentPart::Text(_)))
108→                .count();
109→            let image_count = parts
110→                .iter()
111→                .filter(|p| matches!(p, ContentPart::Image { .. }))
112→                .count();
113→            debug!(
114→                text_count,
115→                image_count,
116→                total_blocks = blocks.len(),
117→                "to_user_content: converted multimodal content"
118→            );
119→            UserContent::Multimodal(parts)
120→        },
121→    }
122→}
