124→pub(crate) fn rewrite_multimodal_text_blocks(
125→    blocks: &[ContentBlock],
126→    new_text: &str,
127→) -> Vec<ContentBlock> {
128→    let mut rewritten = Vec::with_capacity(blocks.len().max(1));
129→    let mut inserted_text = false;
130→
131→    for block in blocks {
132→        match block {
133→            ContentBlock::Text { .. } if !inserted_text => {
134→                rewritten.push(ContentBlock::Text {
135→                    text: new_text.to_string(),
136→                });
137→                inserted_text = true;
138→            },
139→            ContentBlock::Text { .. } => {},
140→            _ => rewritten.push(block.clone()),
141→        }
142→    }
143→
144→    if !inserted_text {
145→        rewritten.insert(0, ContentBlock::Text {
146→            text: new_text.to_string(),
147→        });
148→    }
149→
150→    rewritten
151→}
