158→    match message_content {
159→        MessageContent::Text(text) => {
160→            *text = new_text.to_string();
161→            if let Some(params_obj) = params.as_object_mut() {
162→                params_obj.insert("text".to_string(), serde_json::json!(new_text));
163→                params_obj.remove("content");
164→            }
165→        },
166→        MessageContent::Multimodal(blocks) => {
167→            let rewritten_blocks = rewrite_multimodal_text_blocks(blocks, new_text);
168→            match serde_json::to_value(&rewritten_blocks) {
169→                Ok(content_value) => {
