172→                        params_obj.insert("content".to_string(), content_value);
173→                        params_obj.remove("text");
174→                        params_obj.remove("message");
175→                    }
176→                },
177→                Err(e) => {
178→                    warn!(error = %e, "failed to serialize rewritten multimodal content");
179→                },
180→            }
181→        },
182→    }
183→}
