 54→/// JSON file-backed index mapping session key → SessionEntry.
 55→pub struct SessionMetadata {
 56→    path: PathBuf,
 57→    entries: HashMap<String, SessionEntry>,
 58→}
 59→
 60→fn now_ms() -> u64 {
 61→    SystemTime::now()
 62→        .duration_since(UNIX_EPOCH)
 63→        .unwrap_or_default()
 64→        .as_millis() as u64
 65→}
 66→
 67→fn compare_sidebar_order(lhs: &SessionEntry, rhs: &SessionEntry) -> Ordering {
 68→    let lhs_main = lhs.key == "main";
 69→    let rhs_main = rhs.key == "main";
 70→
 71→    rhs_main
 72→        .cmp(&lhs_main)
 73→        .then_with(|| rhs.updated_at.cmp(&lhs.updated_at))
 74→        .then_with(|| rhs.created_at.cmp(&lhs.created_at))
 75→        .then_with(|| lhs.key.cmp(&rhs.key))
 76→}
 77→
 78→impl SessionMetadata {
 79→    /// Load metadata from disk, or create an empty index.
 80→    pub fn load(path: PathBuf) -> Result<Self> {
 81→        let entries = if path.exists() {
 82→            let data = fs::read_to_string(&path)?;
 83→            serde_json::from_str(&data).unwrap_or_default()
 84→        } else {
 85→            HashMap::new()
 86→        };
 87→        Ok(Self { path, entries })
 88→    }
 89→
 90→    /// Persist metadata to disk.
 91→    pub fn save(&self) -> Result<()> {
 92→        if let Some(parent) = self.path.parent() {
 93→            fs::create_dir_all(parent)?;
 94→        }
 95→        let data = serde_json::to_string_pretty(&self.entries)?;
 96→        fs::write(&self.path, data)?;
 97→        Ok(())
 98→    }
 99→
100→    /// Get an entry by key.
101→    pub fn get(&self, key: &str) -> Option<&SessionEntry> {
102→        self.entries.get(key)
103→    }
104→
105→    /// Insert or update an entry. If key doesn't exist, creates a new entry.
106→    pub fn upsert(&mut self, key: &str, label: Option<String>) -> &SessionEntry {
107→        let now = now_ms();
108→        self.entries
109→            .entry(key.to_string())
110→            .and_modify(|e| {
111→                if let Some(ref l) = label
112→                    && e.label.as_deref() != Some(l)
113→                {
114→                    e.label = label.clone();
115→                    e.updated_at = now;
116→                    e.version += 1;
117→                }
118→            })
119→            .or_insert_with(|| SessionEntry {
120→                id: uuid::Uuid::new_v4().to_string(),
121→                key: key.to_string(),
122→                label,
123→                model: None,
124→                created_at: now,
125→                updated_at: now,
126→                message_count: 0,
127→                last_seen_message_count: 0,
128→                project_id: None,
129→                archived: false,
130→                worktree_branch: None,
131→                sandbox_enabled: None,
132→                sandbox_image: None,
133→                channel_binding: None,
134→                parent_session_key: None,
135→                fork_point: None,
136→                mcp_disabled: None,
137→                preview: None,
138→                agent_id: None,
139→                node_id: None,
140→                version: 0,
141→            })
142→    }
143→
144→    /// Update the model associated with a session.
145→    pub fn set_model(&mut self, key: &str, model: Option<String>) {
146→        if let Some(entry) = self.entries.get_mut(key) {
147→            entry.model = model;
148→            entry.updated_at = now_ms();
149→            entry.version += 1;
150→        }
151→    }
152→
153→    /// Update message count and updated_at timestamp.
154→    pub fn touch(&mut self, key: &str, message_count: u32) {
155→        if let Some(entry) = self.entries.get_mut(key) {
156→            entry.message_count = message_count;
157→            entry.updated_at = now_ms();
158→            entry.version += 1;
159→        }
160→    }
161→
162→    /// Set the project_id for a session.
163→    pub fn set_project_id(&mut self, key: &str, project_id: Option<String>) {
164→        if let Some(entry) = self.entries.get_mut(key) {
165→            entry.project_id = project_id;
166→            entry.updated_at = now_ms();
167→            entry.version += 1;
168→        }
169→    }
170→
171→    /// Set the archived flag for a session.
172→    pub fn set_archived(&mut self, key: &str, archived: bool) {
173→        if let Some(entry) = self.entries.get_mut(key) {
174→            entry.archived = archived;
175→            entry.updated_at = now_ms();
176→            entry.version += 1;
177→        }
178→    }
179→
180→    /// Set the worktree branch for a session.
181→    pub fn set_worktree_branch(&mut self, key: &str, branch: Option<String>) {
182→        if let Some(entry) = self.entries.get_mut(key) {
183→            entry.worktree_branch = branch;
184→            entry.updated_at = now_ms();
185→            entry.version += 1;
186→        }
187→    }
188→
189→    /// Set the sandbox_image for a session.
190→    pub fn set_sandbox_image(&mut self, key: &str, image: Option<String>) {
191→        if let Some(entry) = self.entries.get_mut(key) {
192→            entry.sandbox_image = image;
193→            entry.updated_at = now_ms();
194→            entry.version += 1;
195→        }
196→    }
197→
198→    /// Set the sandbox_enabled override for a session.
199→    pub fn set_sandbox_enabled(&mut self, key: &str, enabled: Option<bool>) {
200→        if let Some(entry) = self.entries.get_mut(key) {
201→            entry.sandbox_enabled = enabled;
202→            entry.updated_at = now_ms();
203→            entry.version += 1;
204→        }
205→    }
206→
207→    /// Set the mcp_disabled override for a session.
208→    pub fn set_mcp_disabled(&mut self, key: &str, disabled: Option<bool>) {
209→        if let Some(entry) = self.entries.get_mut(key) {
210→            entry.mcp_disabled = disabled;
211→            entry.updated_at = now_ms();
212→            entry.version += 1;
213→        }
214→    }
215→
216→    /// Set the channel binding for a session.
217→    pub fn set_channel_binding(&mut self, key: &str, binding: Option<String>) {
218→        if let Some(entry) = self.entries.get_mut(key) {
219→            entry.channel_binding = binding;
220→            entry.updated_at = now_ms();
221→            entry.version += 1;
222→        }
223→    }
224→
225→    /// Assign (or unassign) a session to an agent persona.
226→    pub fn set_agent_id(&mut self, key: &str, agent_id: Option<String>) {
227→        if let Some(entry) = self.entries.get_mut(key) {
228→            entry.agent_id = agent_id;
229→            entry.updated_at = now_ms();
230→            entry.version += 1;
231→        }
232→    }
233→
234→    /// Assign (or unassign) a session to a remote node.
235→    pub fn set_node_id(&mut self, key: &str, node_id: Option<String>) {
236→        if let Some(entry) = self.entries.get_mut(key) {
237→            entry.node_id = node_id;
238→            entry.updated_at = now_ms();
239→            entry.version += 1;
240→        }
241→    }
242→
243→    /// List all sessions belonging to a given agent.
244→    pub fn list_by_agent_id(&self, agent_id: &str) -> Vec<SessionEntry> {
245→        let mut entries: Vec<_> = self
246→            .entries
247→            .values()
248→            .filter(|e| e.agent_id.as_deref() == Some(agent_id))
249→            .cloned()
250→            .collect();
251→        entries.sort_by_key(|a| a.created_at);
252→        entries
253→    }
254→
255→    /// Delete all sessions belonging to a given agent. Returns the number of
256→    /// sessions removed.
257→    pub fn delete_by_agent_id(&mut self, agent_id: &str) -> u64 {
258→        let keys: Vec<String> = self
259→            .entries
260→            .iter()
261→            .filter(|(_, e)| e.agent_id.as_deref() == Some(agent_id))
262→            .map(|(k, _)| k.clone())
263→            .collect();
264→        let count = keys.len() as u64;
265→        for key in keys {
266→            self.entries.remove(&key);
267→        }
268→        count
269→    }
270→
271→    /// Remove an entry by key. Returns the removed entry if found.
272→    pub fn remove(&mut self, key: &str) -> Option<SessionEntry> {
273→        self.entries.remove(key)
274→    }
275→
276→    /// List all entries for sidebar rendering.
277→    /// `main` is pinned first, then sessions are sorted by recency.
278→    pub fn list(&self) -> Vec<SessionEntry> {
279→        let mut entries: Vec<_> = self.entries.values().cloned().collect();
280→        entries.sort_by(compare_sidebar_order);
281→        entries
282→    }
283→}
