 35→impl LiveChatService {
 36→    #[tracing::instrument(skip(self, params), fields(session_id))]
 37→    pub(super) async fn send_impl(&self, mut params: Value) -> ServiceResult {
 38→        // Support both text-only and multimodal content.
 39→        // - "text": string → plain text message
 40→        // - "content": array → multimodal content (text + images)
 41→        //
 42→        // Note: `text` and `message_content` are `mut` because a
 43→        // `MessageReceived` hook may return `ModifyPayload` to rewrite the
 44→        // inbound message before the turn begins (see GH #639).
 45→        let (mut text, mut message_content) = if let Some(content) = params.get("content") {
 46→            // Multimodal content - extract text for logging/hooks, parse into typed blocks
 47→            let text_part = content
 48→                .as_array()
 49→                .and_then(|arr| {
 50→                    arr.iter()
 51→                        .find(|block| block.get("type").and_then(|t| t.as_str()) == Some("text"))
 52→                        .and_then(|block| block.get("text").and_then(|t| t.as_str()))
 53→                })
 54→                .unwrap_or("[Image]")
 55→                .to_string();
 56→
 57→            // Parse JSON blocks into typed ContentBlock structs
 58→            let blocks: Vec<ContentBlock> = content
 59→                .as_array()
 60→                .map(|arr| {
 61→                    arr.iter()
 62→                        .filter_map(|block| {
 63→                            let block_type = block.get("type")?.as_str()?;
 64→                            match block_type {
 65→                                "text" => {
 66→                                    let text = block.get("text")?.as_str()?.to_string();
 67→                                    Some(ContentBlock::text(text))
 68→                                },
 69→                                "image_url" => {
 70→                                    let url = block.get("image_url")?.get("url")?.as_str()?;
 71→                                    Some(ContentBlock::ImageUrl {
 72→                                        image_url: moltis_sessions::message::ImageUrl {
 73→                                            url: url.to_string(),
 74→                                        },
 75→                                    })
 76→                                },
 77→                                _ => None,
 78→                            }
 79→                        })
 80→                        .collect()
 81→                })
 82→                .unwrap_or_default();
 83→            (text_part, MessageContent::Multimodal(blocks))
 84→        } else {
 85→            let text = params
 86→                .get("text")
 87→                .or_else(|| params.get("message"))
 88→                .and_then(|v| v.as_str())
 89→                .ok_or_else(|| "missing 'text', 'message', or 'content' parameter".to_string())?
 90→                .to_string();
 91→            (text.clone(), MessageContent::Text(text))
 92→        };
 93→        let desired_reply_medium = infer_reply_medium(&params, &text);
 94→
 95→        let conn_id = params
 96→            .get("_conn_id")
 97→            .and_then(|v| v.as_str())
 98→            .map(String::from);
 99→        let explicit_model = params.get("model").and_then(|v| v.as_str());
100→        // Use streaming-only mode if explicitly requested or if no tools are registered.
101→        let explicit_stream_only = params
102→            .get("stream_only")
103→            .and_then(|v| v.as_bool())
104→            .unwrap_or(false);
105→        let has_tools = self.has_tools_sync();
106→        let stream_only = explicit_stream_only || !has_tools;
107→        tracing::debug!(
108→            explicit_stream_only,
109→            has_tools,
110→            stream_only,
111→            "send() mode decision"
112→        );
113→
114→        // Resolve session key from explicit overrides, public request params, or connection context.
115→        let session_key = self.resolve_session_key_from_params(&params).await;
116→        let queued_replay = params
117→            .get("_queued_replay")
118→            .and_then(|v| v.as_bool())
119→            .unwrap_or(false);
120→
121→        // Track client-side sequence number for ordering diagnostics.
122→        // Note: seq resets to 1 on page reload, so a drop from a high value
123→        // back to 1 is normal (new browser session) — only flag issues within
124→        // a continuous ascending sequence.
125→        let client_seq = params.get("_seq").and_then(|v| v.as_u64());
126→        if let Some(seq) = client_seq {
127→            if queued_replay {
128→                debug!(
129→                    session = %session_key,
130→                    seq,
131→                    "client seq replayed from queue; skipping ordering diagnostics"
132→                );
133→            } else {
134→                let mut seq_map = self.last_client_seq.write().await;
135→                let last = seq_map.entry(session_key.clone()).or_insert(0);
136→                if *last == 0 {
137→                    // First observed sequence for this session in this process.
138→                    // We cannot infer a gap yet because earlier messages may have
139→                    // come from another tab/process before we started tracking.
140→                    debug!(session = %session_key, seq, "client seq initialized");
141→                } else if seq == 1 && *last > 1 {
142→                    // Page reload — reset tracking.
143→                    debug!(
144→                        session = %session_key,
145→                        prev_seq = *last,
146→                        "client seq reset (page reload)"
147→                    );
148→                } else if seq <= *last {
149→                    warn!(
150→                        session = %session_key,
151→                        seq,
152→                        last_seq = *last,
153→                        "client seq out of order (duplicate or reorder)"
154→                    );
155→                } else if seq > *last + 1 {
156→                    warn!(
157→                        session = %session_key,
158→                        seq,
159→                        last_seq = *last,
160→                        gap = seq - *last - 1,
161→                        "client seq gap detected (missing messages)"
162→                    );
163→                }
164→                *last = seq;
165→            }
166→        }
167→
168→        let explicit_shell_command = match &message_content {
169→            MessageContent::Text(raw) => parse_explicit_shell_command(raw).map(str::to_string),
170→            MessageContent::Multimodal(_) => None,
171→        };
172→
173→        if let Some(shell_command) = explicit_shell_command {
174→            // Generate run_id early so we can link the user message to this run.
175→            let run_id = uuid::Uuid::new_v4().to_string();
176→            let run_id_clone = run_id.clone();
177→            let channel_meta = params.get("channel").cloned();
178→            let user_audio = user_audio_path_from_params(&params, &session_key);
179→            let user_documents =
180→                user_documents_from_params(&params, &session_key, self.session_store.as_ref());
181→            let user_msg = PersistedMessage::User {
182→                content: message_content,
183→                created_at: Some(now_ms()),
184→                audio: user_audio,
185→                documents: user_documents
186→                    .as_deref()
187→                    .and_then(user_documents_for_persistence),
188→                channel: channel_meta,
189→                seq: client_seq,
190→                run_id: Some(run_id.clone()),
191→            };
192→
193→            let history = self
194→                .session_store
195→                .read(&session_key)
196→                .await
197→                .unwrap_or_default();
198→            let user_message_index = history.len();
199→
200→            // Ensure the session exists in metadata and counts are up to date.
201→            let _ = self.session_metadata.upsert(&session_key, None).await;
202→            self.session_metadata
203→                .touch(&session_key, history.len() as u32)
204→                .await;
205→
206→            // If this is a web UI message on a channel-bound session, attach the
